probe_sources.corpus-unsorted:
-- checks: unsorted next and pairs observations from the existing corpus input.
-- KEYS: []
-- ARGV: []
-- expects: No pre-existing keys.
local t={alpha=1,beta=2,gamma=3}
local a,b={},{}
local k=next(t)
while k do a[#a+1]=k .. "=" .. t[k]; k=next(t,k) end
for k,v in pairs(t) do b[#b+1]=k .. "=" .. v end

return {table.concat(a,"|"),table.concat(b,"|"),tostring(next({}) == nil)}
